mapper.select:
SELECT id, expires_at
FROM lot l
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND expires_at IS NOT NULL
AND expires_at<=#{now}
AND NOT EXISTS (SELECT 1 FROM expiry_notice n WHERE n.enterprise_id=l.enterprise_id
  AND n.warehouse_id=l.warehouse_id AND n.lot_id=l.id AND n.window_id=#{windowId})
ORDER BY id
LIMIT #{limit}

mapper.insert:
INSERT INTO expiry_notice (id, enterprise_id, warehouse_id, lot_id, window_id, expires_at, open_reservations, version, created_at, updated_at)
VALUES (#{id}, #{enterpriseId}, #{warehouseId}, #{lotId}, #{windowId}, #{expiresAt}, #{openReservations}, 0, #{now}, #{now})
ON DUPLICATE KEY UPDATE open_reservations=VALUES(open_reservations), updated_at=#{now}

mapper.select:
SELECT COUNT(*)
FROM expiry_notice
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND lot_id=#{lotId}
AND window_id=#{windowId}
